<script setup>
import { computed, ref, watch } from 'vue'
import { state, changeHours } from '../composables/useMonitor.js'
import { now, region } from '../composables/useView.js'
import { probes, probeLabel, timestamp, gpuInfo } from '../utils/metrics.js'
import { billing, daysLeft, loadValues, traffic, probeTone } from '../utils/display.js'
import { probeValueText, rowDiskIo } from '../utils/probes.js'
import { number, memory, size, ratio, percentage, running, uptime, virtualization, dateText, average, maximum, minimum, counterDifference, activityBuckets, colors, rowTime } from './data.js'
import MatrixPlot from './MatrixPlot.vue'
import Sparkline from './Sparkline.vue'
import { dailyTraffic } from '../utils/dailyTraffic.js'
import DonutPanel from './DonutPanel.vue'
import Icon from '../components/Icon.vue'
const server=computed(()=>state.detail), site=computed(()=>state.sites[state.page?.site||0])
const tab=ref('resources'), resourceView=ref('all'), latencyView=ref('compare'), lossMode=ref(false), trim=ref(false), hidden=ref([]), hoveredHeat=ref(null)
let latencyOpened=false
function openTab(value){tab.value=value;if(value==='latency'&&!latencyOpened){latencyOpened=true;if(state.hours!==24)void changeHours(24)}}
watch(()=>`${state.page?.site||0}:${state.page?.id}`,()=>{latencyOpened=false;tab.value='resources'})
const labels={all:'全景仪表',curves:'时序曲线',heat:'负载热力',donuts:'占比饼图',connections:'连接进程'}
const ranges=[{hours:.167,label:'实时'},{hours:1,label:'1 小时'},{hours:6,label:'6 小时'},{hours:24,label:'1 天'},{hours:168,label:'7 天'},{hours:720,label:'30 天'}]
const rangeLabel=computed(()=>ranges.find(item=>item.hours===state.hours)?.label||`${state.hours} 小时`)
const rows=computed(()=>state.rows), times=computed(()=>rows.value.map(row=>row.timestamp??row.last_updated)), live=computed(()=>running(server.value||{},now.value))
const values=key=>rows.value.map(row=>row[key]===null?null:number(row[key])??undefined)
const avg=key=>average(values(key)), max=key=>maximum(values(key))
const buckets=computed(()=>activityBuckets(rows.value,state.hours,now.value))
const coverage=computed(()=>buckets.value.length?buckets.value.filter(bucket=>bucket.count).length/buckets.value.length*100:null)
const heat=computed(()=>hoveredHeat.value===null?null:buckets.value[hoveredHeat.value])
const netRx=computed(()=>counterDifference(rows.value,'net_rx')), netTx=computed(()=>counterDifference(rows.value,'net_tx'))
const quota=computed(()=>traffic(server.value||{}))
const charts=computed(()=>{
 const current=server.value||{}
 return [
 {title:'CPU 核心使用率走势',subtitle:`当前: ${percentage(current.cpu)} · 均值: ${percentage(avg('cpu'))} · 峰值: ${percentage(max('cpu'))}`,unit:'%',max:100,series:[{label:'CPU',values:values('cpu'),color:'#202020',fill:true}]},
 {title:`物理内存使用趋势（上限 ${memory(current.ram_total)}）`,subtitle:`当前: ${memory(current.ram_used)}（${percentage(ratio(current.ram_used,current.ram_total))}）`,unit:'bytes',max:Number(current.ram_total)>0?Number(current.ram_total)*1048576:undefined,series:[{label:'物理内存',values:values('ram_used').map(v=>number(v)===null?v:Number(v)*1048576),color:'#555',fill:true}]},
 {title:'网络传输速率（对数刻度 · 含历史采样峰值）',subtitle:`峰值: ↓ ${size(max('net_in_speed'))}/s · ↑ ${size(max('net_out_speed'))}/s`,unit:'speed',logarithmic:true,series:[{label:'下行',values:values('net_in_speed'),color:'#555',fill:true},{label:'上行',values:values('net_out_speed'),color:'#999',dash:'3 3'}]},
 {title:`系统磁盘容量（上限 ${memory(current.disk_total)}）`,subtitle:`当前已用: ${memory(current.disk_used)}（${percentage(ratio(current.disk_used,current.disk_total))}）`,unit:'bytes',max:Number(current.disk_total)>0?Number(current.disk_total)*1048576:undefined,series:[{label:'磁盘存储',values:values('disk_used').map(v=>number(v)===null?v:Number(v)*1048576),color:'#888',fill:true}]}
 ]
})
const connectionCharts=computed(()=>{
 const current=server.value||{}, list=[]
 if(number(current.tcp_conn)!==null||number(current.udp_conn)!==null)list.push({title:'网络连接追踪',series:[{label:'TCP',values:values('tcp_conn'),color:'#222'},{label:'UDP',values:values('udp_conn'),color:'#888',dash:'4 3'}]})
 if(number(current.processes)!==null)list.push({title:'系统进程走势',series:[{label:'进程',values:values('processes'),color:'#555',fill:true}]})
 if(number(current.swap_total)>0)list.push({title:'交换分区 Swap 使用趋势',unit:'bytes',series:[{label:'Swap',values:values('swap_used').map(v=>number(v)===null?v:Number(v)*1048576),color:'#666',fill:true}]})
 for(const [field,label,unit] of [['read_bps','磁盘读取','speed'],['write_bps','磁盘写入','speed'],['read_iops','读取 IOPS',' ops/s'],['write_iops','写入 IOPS',' ops/s'],['await_ms','磁盘等待','ms'],['util','磁盘 IO 利用率','%']]) if(rows.value.some(row=>number(rowDiskIo(row)[field])!==null))list.push({title:label,unit,series:[{label,values:rows.value.map(row=>number(rowDiskIo(row)[field])??undefined),color:'#555'}]})
 for(const gpu of gpuInfo(current.gpu_info))for(const [field,label,unit,scale] of [['info','利用率','%',1],['mem_used','显存','bytes',1048576],['sm_clock','SM 时钟',' MHz',1],['power','功耗',' W',1]])if(number(gpu[field])!==null)list.push({title:`${gpu.name||'GPU'} · ${label}`,unit,series:[{label,values:rows.value.map(row=>{const n=number(gpuInfo(row.gpu_info).find(item=>String(item.id)===String(gpu.id))?.[field]);return n===null?undefined:n*scale}),color:'#555'}]})
 return list
})
const probeKeys=computed(()=>probes.filter(key=>(server.value?.[`ping_${key}`]!==false&&server.value?.[`ping_${key}`]!==undefined)||rows.value.some(row=>number(row[`ping_${key}`])!==null||number(row[`loss_${key}`])!==null)))
const probeStats=computed(()=>probeKeys.value.map(key=>{
 const field=`${lossMode.value?'loss':'ping'}_${key}`, measurements=values(field), last=server.value?.[field]
 return {key,label:probeLabel(site.value.config,key),color:colors[probes.indexOf(key)],values:measurements,current:last,avg:average(measurements),min:minimum(measurements),max:maximum(measurements),loss:average(values(`loss_${key}`)),selected:!hidden.value.includes(key)}
}))
const probeSeries=computed(()=>probeStats.value.filter(item=>item.selected).map((item,index)=>({label:item.label,values:item.values,color:item.color,dash:index%3===1?'5 3':index%3===2?'2 3':undefined})))
const rankings=computed(()=>[...probeStats.value].sort((a,b)=>(a.avg??Infinity)-(b.avg??Infinity)))
function solo(key){const other=probeKeys.value.filter(value=>value!==key);hidden.value=hidden.value.length===other.length&&!hidden.value.includes(key)?[]:other}
function toggle(key){hidden.value=hidden.value.includes(key)?hidden.value.filter(item=>item!==key):[...hidden.value,key]}
const dateTime=value=>timestamp(value)?new Date(timestamp(value)).toLocaleString('zh-CN',{hour12:false}):'—'
const heatColor=value=>value===null?'var(--soft)':value<10?'var(--soft)':value<40?'#c5e4d1':value<70?'#f3d782':value<90?'#e9aa79':'#d96969'
</script>
<template><p v-if="!server" class="box empty">正在加载节点…</p><div v-else class="matrix-detail">
 <section class="box detail-banner"><div class="detail-identity"><RouterLink class="facts-back" to="/" aria-label="返回概览">←</RouterLink><img v-if="region(server.region)" class="flag" :src="`${site.base}/flags/${region(server.region).toLowerCase()}.svg`" :alt="region(server.region)"><h1>{{ server.name||server.id }}</h1><span class="chip state-chip"><i :class="{up:live}"/>{{ live?`在线 ${uptime(server,now)}`:timestamp(server.last_updated)?'离线':'未接入' }}</span><small v-if="server.agent_version" class="chip">{{ server.agent_version }}</small><small>{{ region(server.region)||'—' }}</small></div><div class="banner-stats"><span class="chip"><Icon name="clock"/>运行 {{ uptime(server,now) }}</span><span class="chip"><Icon name="pulse"/>负载 {{ loadValues(server.load_avg).map(n=>n.toFixed(2)).join(' / ')||'—' }}</span><span class="chip">↓ 网速 {{ live?`${size(server.net_in_speed)}/s`:'—' }}　↑ {{ live?`${size(server.net_out_speed)}/s`:'—' }}</span></div></section>
 <section class="detail-facts-grid">
  <article class="box fact-panel"><h3><Icon name="server"/>系统与计算架构</h3><dl><div><dt>操作系统</dt><dd :title="`${server.os||''} (${server.kernel_version||'—'})`">{{ server.os||'—' }}（{{ server.kernel_version||'—' }}）</dd></div><div><dt>CPU 处理器</dt><dd :title="server.cpu_info">{{ server.cpu_info||'—' }} × {{ server.cpu_cores||'—' }} 核</dd></div><div><dt>架构 / 虚拟化</dt><dd>{{ server.arch||'—' }} · {{ virtualization(server) }} · {{ server.processes??'—' }} 进程</dd></div></dl></article>
  <article class="box fact-panel"><h3><Icon name="memory"/>内存与存储容量</h3><dl><div v-for="entry in [['物理内存','ram'],['交换分区 Swap','swap'],['磁盘空间','disk']]" :key="entry[1]" class="capacity-fact"><div class="spread"><dt>{{ entry[0] }}</dt><dd>{{ memory(server[`${entry[1]}_used`]) }} / {{ memory(server[`${entry[1]}_total`]) }}</dd></div><div class="track"><i :style="{width:`${ratio(server[`${entry[1]}_used`],server[`${entry[1]}_total`])||0}%`}"/></div></div></dl></article>
  <article class="box fact-panel"><h3><Icon name="pulse"/>网络吞吐与流量</h3><dl><div><dt>实时速率</dt><dd>↓ {{ live?size(server.net_in_speed):'—' }}/s · ↑ {{ live?size(server.net_out_speed):'—' }}/s</dd></div><div><dt>{{ dailyTraffic(server,'rx',now).partial?'今日已观测':'今日流量' }}</dt><dd>↓ {{ size(dailyTraffic(server,'rx',now).value??undefined) }} · ↑ {{ size(dailyTraffic(server,'tx',now).value??undefined) }}</dd></div><div v-if="site.sysConfig.show_tf!==false"><dt>本月用量</dt><dd>{{ quota.detail.replaceAll('iB','B') }}</dd></div></dl></article>
  <article class="box fact-panel"><h3><Icon name="calendar"/>服务周期与连接</h3><dl><div v-if="site.sysConfig.show_price!==false"><dt>资费周期</dt><dd>{{ billing(server,'zh')||'—' }}</dd></div><div v-if="site.sysConfig.show_expire!==false"><dt>到期时间</dt><dd>{{ dateText(server.expire_date) }}</dd></div><div><dt>连接追踪</dt><dd>TCP {{ server.tcp_conn??'—' }} · UDP {{ server.udp_conn??'—' }}</dd></div></dl></article>
 </section>
 <div class="detail-tabs"><div class="segmented"><button :aria-pressed="tab==='resources'" @click="openTab('resources')">资源</button><button :aria-pressed="tab==='latency'" @click="openTab('latency')">网络延迟</button></div><div class="range-tabs"><button v-for="range in ranges" :key="range.hours" :aria-pressed="state.hours===range.hours" :disabled="range.hours>168" :title="range.hours>168?'当前 CF 程序最多保留 7 天历史':range.label" @click="state.hours!==range.hours&&changeHours(range.hours)">{{ range.label }}</button><select :value="state.hours" aria-label="历史趋势" @change="changeHours(Number($event.target.value))"><option v-for="h in [.167,.5,1,6,12,24,48,96,168]" :key="h" :value="h">{{ h===.167?'10 分钟':h===.5?'30 分钟':`${h} 小时` }}</option></select></div></div>
 <p v-if="state.historyLoading" role="status" class="muted">正在加载历史数据…</p>
 <section v-if="tab==='resources'" class="box sla-panel"><div class="spread"><label><Icon name="clock"/>服务可用性 · {{ rangeLabel }} 遥测窗口</label><span>历史采样覆盖 <b>{{ percentage(coverage) }}</b></span></div><div class="sla-blocks"><span v-for="(bucket,index) in buckets" :key="index" :class="{present:bucket.count}" :title="`${dateTime(bucket.begin)} — ${dateTime(bucket.end)} · ${bucket.count} 个采样`"/></div><div class="spread muted"><small>{{ rangeLabel }}前</small><small>● 有采样　○ 无采样（不等同精确 SLA）</small><small>当前</small></div></section>
 <template v-if="tab==='resources'"><div class="analysis-heading spread"><strong><Icon name="pulse"/>主机资源分析测控 <small>· 涵盖最近 {{ rangeLabel }} · 共 {{ rows.length }} 采样点</small></strong><nav class="segmented"><button v-for="(label,key) in labels" :key="key" :aria-pressed="resourceView===key" @click="resourceView=key">{{ label }}</button></nav></div>
 <section class="resource-summary"><article class="box"><label><Icon name="cpu"/>CPU 核心负荷</label><b>{{ percentage(server.cpu) }}</b><div class="track"><i :style="{width:`${Math.min(100,Number(server.cpu)||0)}%`}"/></div><div class="spread muted"><small>窗口均值 {{ percentage(avg('cpu')) }}</small><small>窗口峰值 {{ percentage(max('cpu')) }}</small></div></article><article class="box"><label><Icon name="memory"/>物理内存占用</label><b>{{ percentage(ratio(server.ram_used,server.ram_total)) }}</b><div class="track"><i :style="{width:`${ratio(server.ram_used,server.ram_total)||0}%`}"/></div><div class="spread muted"><small>实时 {{ memory(server.ram_used) }}</small><small>均值 {{ memory(avg('ram_used')) }}</small></div></article><article class="box"><label><Icon name="disk"/>系统存储占用</label><b>{{ percentage(ratio(server.disk_used,server.disk_total)) }}</b><div class="track"><i :style="{width:`${ratio(server.disk_used,server.disk_total)||0}%`}"/></div><div class="spread muted"><small>已用 {{ memory(server.disk_used) }}</small><small>总量 {{ memory(server.disk_total) }}</small></div></article><article class="box"><label><Icon name="pulse"/>网络带宽吞吐</label><b>月配额 {{ quota.limit?percentage(quota.percentage):'∞' }}</b><div class="track"><i :style="{width:`${Math.min(100,quota.percentage||0)}%`}"/></div><div class="spread muted"><small>均值 ↓ {{ size(avg('net_in_speed')) }}/s</small><small>均值 ↑ {{ size(avg('net_out_speed')) }}/s</small></div></article></section>
 <section v-if="resourceView==='all'||resourceView==='donuts'" class="donut-grid"><DonutPanel title="物理内存分布比例" :value="ratio(server.ram_used,server.ram_total)" label="已用占比" :left="`已用: ${memory(server.ram_used)}`" :right="`可用: ${memory(number(server.ram_total)!==null&&number(server.ram_used)!==null?Number(server.ram_total)-Number(server.ram_used):undefined)}`"/><DonutPanel title="存储空间分布比例" :value="ratio(server.disk_used,server.disk_total)" label="占用比例" :left="`已用: ${memory(server.disk_used)}`" :right="`剩余: ${memory(number(server.disk_total)!==null&&number(server.disk_used)!==null?Number(server.disk_total)-Number(server.disk_used):undefined)}`" :colors="['#555','#999']"/><DonutPanel title="当前窗口流量构成" :value="netRx!==null&&netTx!==null&&netRx+netTx>0?netTx/(netRx+netTx)*100:null" :label="netTx===null||netRx===null?'未提供窗口计数':!(netTx+netRx)?'暂无流量':netTx>=netRx?'↑ 出网主导':'↓ 入网主导'" :left="`下行: ${size(netRx)}`" :right="`上行: ${size(netTx)}`" :colors="['#222','#888']"/></section>
 <section v-if="resourceView==='all'||resourceView==='heat'" class="box heat-panel"><div class="spread"><strong><Icon name="pulse"/>24 时段负荷活动热力矩阵</strong><small class="muted">低负荷 (0%) <i class="heat-scale"/> 过载 (100%)</small></div><div class="heat-grid"><button v-for="(bucket,index) in buckets" :key="index" :style="{background:heatColor(bucket.cpu)}" :aria-label="`${dateTime(bucket.begin)} CPU ${percentage(bucket.cpu)}`" @mouseenter="hoveredHeat=index" @focus="hoveredHeat=index"><small>{{ new Date(bucket.begin).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) }}</small><b>{{ percentage(bucket.cpu) }}</b></button></div><div class="heat-info"><template v-if="heat"><b>{{ dateTime(heat.begin) }}</b><span>平均 CPU: {{ percentage(heat.cpu) }}</span><span>CPU 峰值: {{ percentage(heat.peak) }}</span><span>内存: {{ memory(heat.ram) }}</span><span>速率: ↓ {{ size(heat.rx) }}/s · ↑ {{ size(heat.tx) }}/s</span></template><span v-else class="muted">鼠标悬停上方任意时段热力方块，即时查看对应时段 CPU 峰值、内存使用与流量详情</span></div></section>
 <section v-if="resourceView==='all'||resourceView==='curves'" class="resource-curves"><MatrixPlot v-for="chart in charts" :key="chart.title" v-bind="chart" :times="times" :gap-ms="state.historyInterval*3"/></section><section v-if="resourceView==='connections'" class="connection-curves"><MatrixPlot v-for="chart in connectionCharts" :key="chart.title" v-bind="chart" :times="times" :gap-ms="state.historyInterval*3"/><p v-if="!connectionCharts.length" class="box empty">当前节点未提供连接进程或扩展指标</p></section>
 </template>
 <section v-else class="latency-panel"><div class="analysis-heading spread"><strong><Icon name="network"/>网络延迟拓扑测控 <small class="chip">{{ probeKeys.length }} 条测试线路</small><small>· 涵盖最近 {{ rangeLabel }}</small></strong><div class="latency-controls"><label><input v-model="trim" type="checkbox">智能削峰</label><div class="segmented"><button v-for="view in [{key:'compare',label:'聚合对比'},{key:'matrix',label:'分轨矩阵'},{key:'ranking',label:'延迟排行'}]" :key="view.key" :aria-pressed="latencyView===view.key" @click="latencyView=view.key">{{ view.label }}</button></div><button :aria-pressed="lossMode" @click="lossMode=!lossMode">{{ lossMode?'丢包率':'延迟' }}</button></div></div>
 <section class="probe-cards probe-selectors"><article v-for="probe in probeStats" :key="probe.key" class="box probe-card" role="button" tabindex="0" :aria-pressed="probe.selected" @click="toggle(probe.key)" @keydown.enter.self.prevent="toggle(probe.key)" @keydown.space.self.prevent="toggle(probe.key)"><div class="spread"><strong><i :style="{background:probe.color}"/>{{ probe.label }}</strong><small :class="probeTone(probe.current,lossMode)">{{ probe.current===null?'超时':number(probe.current)===null?'无采样':lossMode?'丢包率':Number(probe.current)<80?'优秀':Number(probe.current)<240?'一般':'较高' }}</small></div><div class="probe-current"><strong>{{ probe.current===null&&!lossMode?'超时':probeValueText(probe.current,lossMode) }}</strong><Sparkline focused :values="probe.values" :color="probe.color"/></div><div class="spread muted"><span>均 {{ probeValueText(probe.avg,lossMode) }} · 极 {{ number(probe.min)===null?'—':probeValueText(probe.min,lossMode) }}–{{ probeValueText(probe.max,lossMode) }}</span><button class="solo-button" :aria-label="`${probe.label} 单线聚焦`" @click.stop="solo(probe.key)">单线</button></div></article></section>
 <MatrixPlot v-if="latencyView==='compare'" :key="`compare-${lossMode}`" :title="`多线路时序${lossMode?'丢包率':'延迟'}对比（已选 ${probeSeries.length}/${probeKeys.length} 线）`" subtitle="拖动底部滑块可缩放时间区间" :series="probeSeries" :times="times" :gap-ms="state.historyInterval*3" :unit="lossMode?'%':'ms'" :timeouts="!lossMode" :max="lossMode?100:undefined" :floating="!lossMode" :trim="trim" :height="410" zoom/>
 <section v-else-if="latencyView==='matrix'" class="latency-matrix"><MatrixPlot v-for="probe in probeStats.filter(p=>p.selected)" :key="`${probe.key}-${lossMode}`" :title="probe.label" :subtitle="`平均 ${probeValueText(probe.avg,lossMode)}`" :series="[{label:probe.label,values:probe.values,color:probe.color}]" :times="times" :gap-ms="state.historyInterval*3" :unit="lossMode?'%':'ms'" :trim="trim" :max="lossMode?100:undefined" zoom/></section>
 <section v-else class="box latency-ranking"><div class="plot-heading"><strong>{{ lossMode?'丢包率':'网络延迟' }}排行榜</strong><small>当前范围 · 有效采样平均值</small></div><div v-for="(probe,index) in rankings" :key="probe.key" class="ranking-row"><span class="chip">{{ index+1 }}</span><strong>{{ probe.label }}</strong><div class="track"><i :style="{background:probe.color,width:probe.avg===null?'0%':`${probe.avg/Math.max(1,...rankings.map(p=>p.avg||0))*100}%`}"/></div><b>{{ probeValueText(probe.avg,lossMode) }}</b><span class="muted">丢包 {{ probeValueText(probe.loss,true) }}</span></div></section><p v-if="!probeKeys.length" class="box empty">当前节点没有可用的网络探测线路</p><p class="data-caption">平均值仅统计当前范围的有效采样，零值保留；缺失不计作丢包。{{ trim?'智能削峰仅调整图表显示范围，不改变原始统计。':'' }}</p>
 </section>
</div></template>
